// Parse Google Drive folder URL/ID từ input
const body = $input.first().json.body || $input.first().json;

let folderUrl = body.folderUrl || body.folder_url || '';
let folderIdMatch = folderUrl.match(/folders\/([a-zA-Z0-9_-]+)/);
let folderId = folderIdMatch ? folderIdMatch[1] : folderUrl.trim();

if (!folderId) {
  throw new Error('Vui lòng cung cấp folderUrl hoặc folderId hợp lệ từ Google Drive');
}

const quizTitle = body.quizTitle || body.quiz_title || 'Quiz từ tài liệu Markdown';
const questionsPerFile = parseInt(body.questionsPerFile || body.questions_per_file || '3');
const description = body.description || 'Bộ câu hỏi được tạo tự động từ tài liệu';

console.log(`Folder ID: ${folderId}`);
console.log(`Quiz Title: ${quizTitle}`);
console.log(`Questions per file: ${questionsPerFile}`);

return [{
  json: {
    folderId,
    folderUrl,
    quizTitle,
    questionsPerFile,
    description
  }
}];

// Lọc chỉ lấy các file Markdown (.md)
const allFiles = $input.all();
const folderId = $('Parse Input & Extract Folder ID').first().json.folderId;
const quizTitle = $('Parse Input & Extract Folder ID').first().json.quizTitle;
const questionsPerFile = $('Parse Input & Extract Folder ID').first().json.questionsPerFile;
const description = $('Parse Input & Extract Folder ID').first().json.description;

console.log(`Total files found: ${allFiles.length}`);

const markdownFiles = allFiles.filter(item => {
  const name = item.json.name || '';
  const mimeType = item.json.mimeType || '';
  // Lấy .md files và text/plain (Google Drive có thể lưu .md dưới dạng text/plain)
  return name.endsWith('.md') || 
         name.endsWith('.markdown') ||
         mimeType === 'text/markdown' ||
         (mimeType === 'text/plain' && (name.endsWith('.md') || name.endsWith('.markdown')));
});

console.log(`Markdown files found: ${markdownFiles.length}`);

if (markdownFiles.length === 0) {
  throw new Error(`Không tìm thấy file Markdown (.md) nào trong folder: ${folderId}`);
}

// Truyền metadata cho các bước tiếp theo
return markdownFiles.map(item => ({
  json: {
    fileId: item.json.id,
    fileName: item.json.name,
    mimeType: item.json.mimeType,
    modifiedTime: item.json.modifiedTime,
    quizTitle,
    questionsPerFile,
    description,
    totalFiles: markdownFiles.length
  }
}));

// Convert binary data to text và chuẩn bị cho AI
const item = $input.first();
const binaryData = item.binary?.data;
const jsonData = item.json;

let markdownContent = '';

if (binaryData) {
  // Decode base64 binary content
  const base64Content = binaryData.data;
  markdownContent = Buffer.from(base64Content, 'base64').toString('utf-8');
} else if (jsonData.data) {
  markdownContent = jsonData.data;
}

// Giới hạn content để tránh vượt token limit của AI
const maxLength = 8000;
if (markdownContent.length > maxLength) {
  markdownContent = markdownContent.substring(0, maxLength) + '\n... [nội dung bị cắt bớt]';
}

console.log(`File: ${jsonData.fileName}, Content length: ${markdownContent.length}`);

return [{
  json: {
    ...jsonData,
    markdownContent,
    contentLength: markdownContent.length
  }
}];

