// Parse Gemini API response và format câu hỏi
const item = $input.first();

const candidates = item.json.candidates || [];
const aiText = candidates[0]?.content?.parts?.[0]?.text || '';
const finishReason = candidates[0]?.finishReason || 'UNKNOWN';

const fileName = $('Extract Text Content').first().json.fileName;
const quizTitle = $('Extract Text Content').first().json.quizTitle;
const description = $('Extract Text Content').first().json.description;

if (!aiText) {
  throw new Error(`Gemini không trả về nội dung cho file ${fileName}. Finish reason: ${finishReason}`);
}

// Nếu bị dừng ngang do hết token hoặc lý do an toàn
if (finishReason !== 'STOP' && finishReason !== 'UNKNOWN') {
  throw new Error(`Gemini bị ngắt ngang do [${finishReason}] khi xử lý file ${fileName}`);
}

let parsedData;
try {
  let cleanResponse = aiText.replace(/^```json\s*/m, '').replace(/```\s*$/m, '').trim();
  parsedData = JSON.parse(cleanResponse);
} catch (e) {
  console.error('Parse error:', e.message);
  throw new Error(`Không thể parse Gemini response cho file ${fileName}: ${e.message}\nNội dung bị lỗi:\n${aiText.substring(0, 500)}...`);
}

let questions = [];
if (Array.isArray(parsedData)) {
  questions = parsedData; // Trường hợp AI trả thẳng về Array
} else if (parsedData.questions && Array.isArray(parsedData.questions)) {
  questions = parsedData.questions; // Trường hợp chuẩn
} else if (parsedData.quiz && Array.isArray(parsedData.quiz)) {
  questions = parsedData.quiz; 
} else {
  // Tìm mảng bất kỳ trong object
  for (const key in parsedData) {
    if (Array.isArray(parsedData[key])) {
      questions = parsedData[key];
      break;
    }
  }
}

if (questions.length === 0) {
  throw new Error(`Gemini trả về JSON nhưng không tìm thấy danh sách câu hỏi. Nội dung thực tế: ${JSON.stringify(parsedData)}`);
}

return [{
  json: {
    fileName,
    quizTitle,
    description,
    questions,
    questionsCount: questions.length
  }
}];

// Tổng hợp tất cả câu hỏi từ nhiều file (Hỗ trợ mọi định dạng đầu vào)
const items = $input.all();

let allQuestions = [];
let quizTitle = 'Quiz Tự Động';
let description = '';
let processedFiles = 0;

for (const item of items) {
  // Tìm dữ liệu thực sự (xử lý cả khi dùng Aggregate node và không dùng)
  let dataToProcess = [];
  if (item.json.allQuizData && Array.isArray(item.json.allQuizData)) {
    dataToProcess = item.json.allQuizData;
  } else if (item.json.data && Array.isArray(item.json.data)) {
    dataToProcess = item.json.data;
  } else {
    dataToProcess = [item.json];
  }

  // Duyệt qua từng file đã parse
  for (const fileData of dataToProcess) {
    if (fileData.quizTitle) quizTitle = fileData.quizTitle;
    if (fileData.description) description = fileData.description;

    if (fileData.questions && Array.isArray(fileData.questions)) {
      processedFiles++;
      // Thêm source file vào mỗi câu hỏi
      const questionsWithSource = fileData.questions.map(q => ({
        ...q,
        sourceFile: fileData.fileName || 'Unknown File'
      }));
      allQuestions = allQuestions.concat(questionsWithSource);
    }
  }
}

console.log(`Total questions aggregated: ${allQuestions.length}`);

// Bắt lỗi chi tiết nếu vẫn bằng 0
if (allQuestions.length === 0) {
  throw new Error(`Không có câu hỏi nào được tạo. Dữ liệu nhận được: ${JSON.stringify(items[0].json).substring(0, 500)}`);
}

return [{
  json: {
    quizTitle,
    description: description || `Bộ câu hỏi gồm ${allQuestions.length} câu được tạo từ ${processedFiles} tài liệu Markdown`,
    questions: allQuestions,
    totalQuestions: allQuestions.length,
    totalFiles: processedFiles
  }
}];

// Extract Form ID và chuẩn bị để add questions
const createResponse = $input.first().json.body || $input.first().json;
const quizData = $('Merge & Prepare Quiz Data').first().json;

const formId = createResponse.formId;
const formUrl = createResponse.responderUri;

console.log(`Created form ID: ${formId}`);
console.log(`Form URL: ${formUrl}`);

if (!formId) {
  throw new Error('Không thể tạo Google Form: ' + JSON.stringify(createResponse));
}

return [{
  json: {
    formId,
    formUrl,
    editUrl: `https://docs.google.com/forms/d/${formId}/edit`,
    quizTitle: quizData.quizTitle,
    questions: quizData.questions,
    totalQuestions: quizData.totalQuestions,
    totalFiles: quizData.totalFiles
  }
}];

