={{ (() => {
  const formId = $json.formId;
  const questions = $json.questions;

  const requests = [];

  // 1. Cập nhật Description cho Form
  if ($json.description) {
    requests.push({
      "updateFormInfo": {
        "info": {
          "description": $json.description
        },
        "updateMask": "description"
      }
    });
  }

  // 2. Chuyển Form thành dạng Quiz (Chấm điểm)
  requests.push({
    "updateSettings": {
      "settings": {
        "quizSettings": {
          "isQuiz": true
        }
      },
      "updateMask": "quizSettings.isQuiz"
    }
  });

  // 3. Thêm từng câu hỏi vào Form
  questions.forEach((q, index) => {
    const options = Object.entries(q.options || {}).map(([key, value]) => ({
      "value": `${key}. ${value}`
    }));

    const correctKey = q.correctAnswer;
    const correctOptionValue = `${correctKey}. ${(q.options || {})[correctKey]}`;

    requests.push({
      "createItem": {
        "item": {
          "title": q.question,
          "description": q.explanation ? `💡 Giải thích: ${q.explanation}` : '',
          "questionItem": {
            "question": {
              "required": true,
              "grading": {
                "pointValue": 1,
                "correctAnswers": {
                  "answers": [{ "value": correctOptionValue }]
                },
                "whenRight": { "text": "✅ Chính xác!" },
                "whenWrong": { "text": `❌ Đáp án đúng là: ${correctOptionValue}` }
              },
              "choiceQuestion": {
                "type": "RADIO",
                "options": options,
                "shuffle": false
              }
            }
          }
        },
        "location": { "index": index }
      }
    });
  });

  return JSON.stringify({ requests });
})() }}

